def switches(mask):
    if not isinstance(mask,str) or len(mask)!=6 or set(mask)-{'0','1'}:
        raise ValueError('Expected six-bit configuration')
    return tuple(v=='1' for v in mask)

def restore(noisy,mask):
    a,b,c,d,e,f=switches(mask); image=np.array(noisy,copy=True)
    if a:image=median_filter(image,size=5 if f else 3,mode='reflect')
    if b:image=gaussian_filter(image,sigma=1.6 if e else .8,mode='reflect')
    if c:image=wiener(image,mysize=(5,5))
    if d:image=image+.5*(image-gaussian_filter(image,sigma=1.,mode='reflect'))
    return np.clip(image,0,1)
